/**
 * @summary Get backup settings and recent cloud backups
 */
export const GetBackupStatusResponse = zod.object({
  "settings": zod.object({
  "enabled": zod.boolean(),
  "frequency": zod.enum(['daily', 'weekly']),
  "nextRunAt": zod.coerce.date().nullable(),
  "lastRunAt": zod.coerce.date().nullable(),
  "lastStatus": zod.enum(['never', 'completed', 'failed', 'running'])
}),
  "lastSuccessful": zod.union([zod.object({
  "id": zod.string(),
  "createdAt": zod.coerce.date(),
  "completedAt": zod.coerce.date().nullable(),
  "status": zod.enum(['completed', 'failed', 'running']),
  "recordCount": zod.number(),
  "message": zod.string()
}),zod.null()]).optional(),
  "history": zod.array(zod.object({
  "id": zod.string(),
  "createdAt": zod.coerce.date(),
  "completedAt": zod.coerce.date().nullable(),
  "status": zod.enum(['completed', 'failed', 'running']),
  "recordCount": zod.number(),
  "message": zod.string()
}))
})


